/** Builds content/canon/index/names.yaml: every proper name in canon and where it is used. */
import { parse, stringify } from 'yaml';
import { CanonIndex, renderNameIndex } from '../lint/canon-index';
import { entriesOf } from '../lint/load';

export const NAME_INDEX_DIR = 'content/canon/index';

const HEADER =
  '# Generated by `pnpm extract` from the extracted canon. Do not edit by hand.\n' +
  '# Every proper name in canon (places and sub-places, realms, people, groups, faiths,\n' +
  '# schools, careers, Weathers), with the entries that bear it as `kind:id`.\n';

export function nameIndexFiles(
  sources: { outDir: string; files: Map<string, string> }[],
): Map<string, string> {
  const canon = sources.flatMap(({ outDir, files }) =>
    [...files]
      .filter(([name]) => name.endsWith('.yaml'))
      .flatMap(([name, text]) =>
        entriesOf(parse(text)).map((entry) => ({ entry, file: `${outDir}/${name}`, canon: true })),
      ),
  );
  const names = renderNameIndex(new CanonIndex(canon));
  return new Map([['names.yaml', HEADER + stringify(names, { lineWidth: 0 })]]);
}
